/// <reference types="vite/client" />
import { JLPTLevel, SubtitleLineRecord, SubtitleTokenJSON } from '../../schema/databaseSchema';
import { DICTIONARY_WORDS } from '../mockVideos';

/**
 * Real timed captions generated by scripts/fetch-captions.py (one file per youtube_id),
 * with kuromoji tokens added by scripts/tokenize-captions.mjs.
 * Files are lazy-loaded (separate chunks) so they are not part of the main bundle.
 */
export interface RawCaptionToken {
  surface: string;
  lemma: string;
  reading: string; // hiragana
  romaji: string; // Hepburn
  pos: string;
}

export interface CaptionLine {
  start_ms: number;
  end_ms: number;
  ja: string | null;
  th: string | null;
  tokens?: RawCaptionToken[];
}

export interface CaptionFile {
  youtube_id: string;
  source: { ja: string; th: string };
  lines: CaptionLine[];
}

const loaders = import.meta.glob('./*.json') as Record<string, () => Promise<{ default: CaptionFile }>>;

// Cache of load promises keyed by youtube_id. Resolves to undefined when no file exists.
const cache = new Map<string, Promise<CaptionFile | undefined>>();

export const loadRealCaptions = (youtubeId: string): Promise<CaptionFile | undefined> => {
  let p = cache.get(youtubeId);
  if (!p) {
    const loader = loaders[`./${youtubeId}.json`];
    p = loader
      ? loader().then((m) => m.default).catch(() => undefined)
      : Promise.resolve(undefined);
    cache.set(youtubeId, p);
  }
  return p;
};

// First dictionary word id for each lemma, so a token shares its word id with the dictionary.
let lemmaToWordId: Map<string, string> | null = null;
const dictionaryIdFor = (lemma: string): string | undefined => {
  if (!lemmaToWordId) {
    lemmaToWordId = new Map();
    for (const w of DICTIONARY_WORDS) {
      if (!lemmaToWordId.has(w.lemma)) lemmaToWordId.set(w.lemma, w.id);
    }
  }
  return lemmaToWordId.get(lemma);
};

// Pure punctuation / symbols (no letters, digits, kana or kanji).
const isPunctuation = (text: string): boolean => !/[\p{L}\p{N}]/u.test(text);

// Fallback for lines without kuromoji tokens: split on whitespace and punctuation.
const splitJapanese = (text: string): string[] =>
  text
    .split(/[\s、。！？!?,.「」『』（）()［］\[\]【】…・〜~"'“”‘’:：;；]+/)
    .filter((part) => part.length > 0 && /[\p{L}\p{N}]/u.test(part));

const fallbackTokens = (lineId: string, ja: string, jlpt: JLPTLevel): SubtitleTokenJSON[] =>
  splitJapanese(ja).map((surface, tokenIndex) => ({
    surface,
    word_id: `${lineId}-${tokenIndex}`,
    lemma: surface,
    reading_kana: surface,
    romaji: '',
    jlpt_level: jlpt,
    part_of_speech: '',
    contextual_meaning: '',
  }));

/**
 * Tokens from kuromoji. Punctuation is not a tap target: it is appended to the previous
 * token's surface (or prefixed to the next one at the start of a line), so the rendered
 * text keeps it. A token whose lemma matches a dictionary word uses that word's id.
 */
const tokensFromRaw = (lineId: string, raw: RawCaptionToken[], jlpt: JLPTLevel): SubtitleTokenJSON[] => {
  const folded: { surface: string; lemma: string; reading: string; romaji: string; pos: string }[] = [];
  let pendingPrefix = '';
  for (const t of raw) {
    if (isPunctuation(t.surface)) {
      if (folded.length > 0) folded[folded.length - 1].surface += t.surface;
      else pendingPrefix += t.surface;
      continue;
    }
    folded.push({ ...t, surface: pendingPrefix + t.surface });
    pendingPrefix = '';
  }
  return folded.map((t, tokenIndex) => ({
    surface: t.surface,
    word_id: dictionaryIdFor(t.lemma) ?? `${lineId}-${tokenIndex}`,
    lemma: t.lemma,
    reading_kana: t.reading || t.surface,
    romaji: t.romaji,
    jlpt_level: jlpt,
    part_of_speech: t.pos,
    contextual_meaning: '',
  }));
};

const buildTokens = (lineId: string, line: CaptionLine, ja: string, jlpt: JLPTLevel): SubtitleTokenJSON[] =>
  line.tokens ? tokensFromRaw(lineId, line.tokens, jlpt) : fallbackTokens(lineId, ja, jlpt);

/**
 * Builds SubtitleLineRecord[] for one video record from its loaded caption file.
 * Ids: `cap-<videoId>-<start_ms>` (suffix -2, -3 on collision within the video).
 * Thai goes only in thai_translation; natural_translation stays empty so it is not shown twice.
 * Lines without Japanese text get raw_text "" and tokens_json [].
 */
export const buildRealSubtitleLines = (
  file: CaptionFile,
  videoId: string,
  jlpt: JLPTLevel
): SubtitleLineRecord[] => {
  const used = new Map<string, number>();
  return file.lines.map((line, i) => {
    const base = `cap-${videoId}-${line.start_ms}`;
    const count = (used.get(base) ?? 0) + 1;
    used.set(base, count);
    const id = count === 1 ? base : `${base}-${count}`;
    const ja = line.ja ?? '';
    const th = line.th ?? undefined;
    return {
      id,
      video_id: videoId,
      line_index: i,
      start_time_ms: line.start_ms,
      end_time_ms: line.end_ms,
      raw_text: ja,
      natural_translation: '',
      thai_translation: th,
      ai_grammar_summary: '',
      tokens_json: ja ? buildTokens(id, line, ja, jlpt) : [],
    };
  });
};
